"""Read-only Codex research command centre; all market content is untrusted text."""
from inspect import isawaitable
from typing import Literal

from fastapi import Query
from fastapi.responses import HTMLResponse, PlainTextResponse


def attach_routes(app, transcript, paper_provider):
    async def resolve(value):
        return await value if isawaitable(value) else value

    @app.get('/lab', response_class=HTMLResponse)
    def lab_page():
        return PAGE

    @app.get('/api/lab')
    async def lab_snapshot():
        from . import lab_api
        paper = await resolve(paper_provider())
        return await resolve(lab_api.snapshot(transcript, paper))

    @app.get('/api/lab/chart')
    async def lab_chart(timeframe: Literal['M1', 'M5', 'M15', 'H1', 'H4', 'D1'] = 'M1',
                        limit: int = Query(300, ge=10, le=1000)):
        from . import lab_api
        return await resolve(lab_api.chart(timeframe, limit))

    @app.get('/api/lab/events')
    async def lab_events(after: int = Query(0, ge=0), limit: int = Query(100, ge=1, le=200)):
        from . import lab_api
        return await resolve(lab_api.events(transcript, after, limit))

    @app.get('/api/lab/conversation')
    def conversation_entries(before: str | None = Query(None, max_length=100),
                             limit: int = Query(50, ge=1, le=100)):
        from .agent_conversation import ConversationStore
        from .lab_store import LabStore
        return ConversationStore(LabStore(transcript)).entries(before, limit)

    @app.get('/api/lab/conversation/{entry_id}')
    def conversation_page(entry_id: str, offset: int = Query(0, ge=0, le=2100000),
                          limit: int = Query(3000, ge=1, le=12000)):
        from .agent_conversation import ConversationStore
        from .lab_store import LabStore
        return ConversationStore(LabStore(transcript)).page(entry_id, offset, limit)

    @app.get('/api/lab/conversation/{entry_id}/download')
    def conversation_download(entry_id: str):
        from .agent_conversation import ConversationStore
        from .lab_store import LabStore
        content = ConversationStore(LabStore(transcript)).download(entry_id)
        if content is None:
            return PlainTextResponse('Conversation not retained', status_code=404)
        return PlainTextResponse(content, headers={'Content-Disposition': 'attachment; filename="conversation.txt"',
                                                  'X-Content-Type-Options': 'nosniff'})


